create table public.fiscal_tax_catalog(tax_key text primary key,label text not null,level text not null,default_rate numeric,min_rate numeric,max_rate numeric,unit text not null,chapter text not null,explanation text not null,base_key text,source_url text not null);
insert into public.fiscal_tax_catalog select key,label,level,default_rate,min_rate,max_rate,unit,chapter,explanation,base_key,source_url from jsonb_to_recordset('[{"key":"vat","label":"Налог на добавленную стоимость","level":"federal","default_rate":22,"min_rate":0,"max_rate":22,"unit":"%","chapter":"21","explanation":"Добавленная стоимость; отдельные операции 10% или 0%. Базовая ставка с 2026 года 22%.","base_key":"consumption","source_url":"https://www.nalog.gov.ru/new2026/"},{"key":"excise","label":"Акцизы","level":"federal","default_rate":null,"min_rate":null,"max_rate":null,"unit":"По виду товара","chapter":"22","explanation":"Дифференцированные ставки по виду подакцизного товара; не единый процент.","base_key":null,"source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/excise/"},{"key":"income","label":"Налог на доходы физических лиц","level":"federal","default_rate":13,"min_rate":13,"max_rate":22,"unit":"%","chapter":"23","explanation":"Для основной налоговой базы шкала 13/15/18/20/22%. В прогнозе показана эффективная ставка, а не замена прогрессивной шкалы.","base_key":"payroll","source_url":"https://www.nalog.gov.ru/new2025/"},{"key":"profit","label":"Налог на прибыль организаций","level":"federal","default_rate":25,"min_rate":0,"max_rate":25,"unit":"%","chapter":"25","explanation":"Базовая ставка 25%; распределение по бюджетам отдельно от вида налога. Льготы и специальные ставки зависят от норм НК.","base_key":"profit","source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/profitul/"},{"key":"extraction","label":"Налог на добычу полезных ископаемых","level":"federal","default_rate":null,"min_rate":null,"max_rate":null,"unit":"По виду сырья","chapter":"26","explanation":"Специальные ставки и формулы; расчёт зависит от вида сырья, объёма добычи и коэффициентов.","base_key":null,"source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/ndpi/"},{"key":"water","label":"Водный налог","level":"federal","default_rate":null,"min_rate":null,"max_rate":null,"unit":"По бассейну и объёму","chapter":"25.2","explanation":"Налог при специальных видах водопользования; ставки по бассейну и назначению.","base_key":null,"source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/water_tax/"},{"key":"wildlife","label":"Сборы за пользование объектами животного мира и водными биоресурсами","level":"federal","default_rate":null,"min_rate":null,"max_rate":null,"unit":"По объекту","chapter":"25.1","explanation":"Два вида сборов в одной категории статьи 13 НК РФ; разрешения, вид объекта и объём определяют сумму.","base_key":null,"source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/fees/"},{"key":"duty","label":"Государственная пошлина","level":"federal","default_rate":null,"min_rate":null,"max_rate":null,"unit":"По действию","chapter":"25.3","explanation":"Размер зависит от юридически значимого действия. Не относится к единой процентной ставке.","base_key":null,"source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/gosposhlina/"},{"key":"additional_income","label":"Налог на дополнительный доход от добычи углеводородного сырья","level":"federal","default_rate":50,"min_rate":50,"max_rate":50,"unit":"%","chapter":"25.4","explanation":"НДД рассчитывается по специальной базе и условиям главы 25.4; учебная база задаётся преподавателем.","base_key":"oil_income","source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/ndd/"},{"key":"gambling","label":"Налог на игорный бизнес","level":"federal","default_rate":7,"min_rate":7,"max_rate":7,"unit":"%","chapter":"25.5","explanation":"С 2026 года федеральный. Букмекеры и тотализаторы: 7%; стол 250 000 руб., автомат 15 000 руб. в месяц. Разные объекты учитываются отдельно.","base_key":"gambling_income","source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/gambling_tax/"},{"key":"corporate_property","label":"Налог на имущество организаций","level":"regional","default_rate":2.2,"min_rate":0,"max_rate":2.2,"unit":"%","chapter":"30","explanation":"В модели — среднегодовая стоимость, ставка до 2,2%; кадастровая база и специальные пределы рассматриваются отдельно.","base_key":"corporate_assets","source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/imuchorg/"},{"key":"transport","label":"Транспортный налог","level":"regional","default_rate":3.5,"min_rate":0,"max_rate":35,"unit":"руб./л.с.","chapter":"28","explanation":"Учебная группа: легковые автомобили мощностью 100–150 л.с. Базовая федеральная ставка 3,5 руб./л.с.; субъект устанавливает ставку в пределах НК.","base_key":"horsepower","source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/transport/"},{"key":"land","label":"Земельный налог","level":"municipal","default_rate":1.5,"min_rate":0,"max_rate":1.5,"unit":"%","chapter":"31","explanation":"В модели — категория земли с пределом 1,5%; для специальных категорий действует предел 0,3%.","base_key":"land_value","source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/zemelny/"},{"key":"personal_property","label":"Налог на имущество физических лиц","level":"municipal","default_rate":0.1,"min_rate":0,"max_rate":0.3,"unit":"%","chapter":"32","explanation":"В модели — обычное жильё. Для других объектов и дорогой недвижимости нормы и пределы отличаются.","base_key":"housing_value","source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/imuch2016/"},{"key":"trade","label":"Торговый сбор","level":"municipal","default_rate":null,"min_rate":null,"max_rate":null,"unit":"По торговому объекту","chapter":"33","explanation":"Вводится актом представительного органа в предусмотренных НК территориях; не автоматически во всех муниципалитетах.","base_key":null,"source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/trade_fee/"},{"key":"tourism","label":"Туристический налог","level":"municipal","default_rate":2,"min_rate":0,"max_rate":2,"unit":"%","chapter":"33.1","explanation":"Максимальная ставка в 2026 году 2%; минимальный налог и льготы учитываются по главе 33.1. Модель рассчитывает только облагаемую стоимость размещения.","base_key":"tourism_income","source_url":"https://www.nalog.gov.ru/rn77/taxation/taxes/tourist_tax/"}]'::jsonb) as x(key text,label text,level text,default_rate numeric,min_rate numeric,max_rate numeric,unit text,chapter text,explanation text,base_key text,source_url text);
create table public.game_fiscal_regions(
 game_id uuid not null references games(id) on delete cascade,region_code text not null references fiscal_region_reference(code),budget_year integer not null default 2026,
 enterprises integer not null check(enterprises between 0 and 10000000),employees_per_firm numeric not null check(employees_per_firm between 0 and 10000),monthly_wage numeric not null check(monthly_wage between 0 and 10000000),profit_per_firm numeric not null check(profit_per_firm between 0 and 1000000),consumption_per_firm numeric not null check(consumption_per_firm between 0 and 1000000),
 expenditure numeric not null check(expenditure>=0),transfer_in numeric not null default 0 check(transfer_in>=0),debt numeric not null default 0 check(debt>=0),compliance numeric not null default .95 check(compliance between 0 and 1),
 activity_multiplier numeric not null default 1 check(activity_multiplier between .05 and 5),cost_multiplier numeric not null default 1 check(cost_multiplier between .05 and 5),updated_at timestamptz not null default now(),primary key(game_id,region_code));
create table public.game_fiscal_rates(game_id uuid not null references games(id) on delete cascade,region_code text not null default '00',tax_key text not null references fiscal_tax_catalog(tax_key),rate numeric not null check(rate>=0),updated_at timestamptz not null default now(),primary key(game_id,region_code,tax_key));
create table public.fiscal_rate_proposals(id uuid primary key default gen_random_uuid(),game_id uuid not null references games(id) on delete cascade,region_code text not null,tax_key text not null references fiscal_tax_catalog(tax_key),new_rate numeric not null,author_id uuid not null references auth.users(id),document_id uuid references formal_documents(id) on delete set null,status text not null default 'pending',created_at timestamptz not null default now());
create table public.fiscal_change_ledger(id bigint generated always as identity primary key,game_id uuid not null references games(id) on delete cascade,region_code text,source_type text not null,source_id text not null,note text not null,before_values jsonb,after_values jsonb,actor_id uuid,created_at timestamptz not null default now(),unique(game_id,source_type,source_id,region_code));
alter table public.fiscal_region_reference enable row level security;alter table public.fiscal_tax_catalog enable row level security;
create policy fiscal_reference_read on public.fiscal_region_reference for select to authenticated using(true);
create policy fiscal_tax_read on public.fiscal_tax_catalog for select to authenticated using(true);
alter table public.game_fiscal_regions enable row level security;alter table public.game_fiscal_rates enable row level security;alter table public.fiscal_rate_proposals enable row level security;alter table public.fiscal_change_ledger enable row level security;
create policy fiscal_regions_read on public.game_fiscal_regions for select to authenticated using(private.is_game_member(game_id));
create policy fiscal_rates_read on public.game_fiscal_rates for select to authenticated using(private.is_game_member(game_id));
create policy fiscal_proposals_read on public.fiscal_rate_proposals for select to authenticated using(private.is_game_member(game_id));
create policy fiscal_ledger_read on public.fiscal_change_ledger for select to authenticated using(private.is_game_member(game_id));
create or replace function private.ensure_fiscal_game(p_game uuid) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$
begin
 insert into game_fiscal_regions(game_id,region_code,enterprises,employees_per_firm,monthly_wage,profit_per_firm,consumption_per_firm,expenditure,transfer_in,debt)
 select p_game,code,case profile when 'metropolis' then 12000 when 'resources' then 1800 when 'agriculture' then 2400 when 'northern' then 600 when 'tourism' then 1600 else 3200 end,
 case profile when 'resources' then 35 when 'agriculture' then 8 else 14 end,
 case profile when 'metropolis' then 90000 when 'northern' then 85000 when 'resources' then 80000 else 50000 end,
 case profile when 'resources' then 8 when 'metropolis' then 5 else 2 end,
 case profile when 'metropolis' then 12 when 'tourism' then 8 else 4 end,
 case profile when 'metropolis' then 95000 when 'resources' then 25000 when 'northern' then 8000 else 14000 end,
 case profile when 'northern' then 5000 when 'agriculture' then 3000 else 1000 end,case profile when 'metropolis' then 10000 else 2500 end
 from fiscal_region_reference on conflict do nothing;
end $$;
create or replace function public.get_fiscal_budget(p_game_id uuid) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$
declare v_result jsonb;
begin
 if not private.is_game_member(p_game_id) then raise exception 'Нет доступа к бюджету этой игры.';end if;
 perform private.ensure_fiscal_game(p_game_id);
 select jsonb_build_object('regions',(select jsonb_agg(to_jsonb(r)||jsonb_build_object('name',d.name,'profile',d.profile,'disputed',d.disputed,'observations',d.observations,'source_url',d.source_url,'source_year',d.source_year) order by d.name) from game_fiscal_regions r join fiscal_region_reference d on d.code=r.region_code where game_id=p_game_id),'rates',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from game_fiscal_rates t where game_id=p_game_id),'proposals',(select coalesce(jsonb_agg(to_jsonb(t) order by created_at desc),'[]'::jsonb) from fiscal_rate_proposals t where game_id=p_game_id),'ledger',(select coalesce(jsonb_agg(to_jsonb(t) order by created_at desc),'[]'::jsonb) from (select * from fiscal_change_ledger where game_id=p_game_id order by created_at desc limit 100) t),'can_propose',private.is_game_teacher(p_game_id) or exists(select 1 from private.formal_user_roles(p_game_id,auth.uid()) rt where rt ~ 'министр|правительств|губернатор|глава|администрац')) into v_result;
 return v_result;
end $$;
create or replace function public.set_fiscal_parameters(p_game_id uuid,p_region text,p_values jsonb) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$
declare old_row jsonb;new_row jsonb;
begin
 if not private.is_game_teacher(p_game_id) then raise exception 'Параметры экономики задаёт только преподаватель.';end if;
 perform private.ensure_fiscal_game(p_game_id);
 select to_jsonb(r) into old_row from game_fiscal_regions r where game_id=p_game_id and region_code=p_region for update;
 if old_row is null then raise exception 'Регион не найден.';end if;
 update game_fiscal_regions set enterprises=coalesce((p_values->>'enterprises')::integer,enterprises),employees_per_firm=coalesce((p_values->>'employees_per_firm')::numeric,employees_per_firm),monthly_wage=coalesce((p_values->>'monthly_wage')::numeric,monthly_wage),profit_per_firm=coalesce((p_values->>'profit_per_firm')::numeric,profit_per_firm),consumption_per_firm=coalesce((p_values->>'consumption_per_firm')::numeric,consumption_per_firm),expenditure=coalesce((p_values->>'expenditure')::numeric,expenditure),transfer_in=coalesce((p_values->>'transfer_in')::numeric,transfer_in),debt=coalesce((p_values->>'debt')::numeric,debt),compliance=coalesce((p_values->>'compliance')::numeric,compliance),updated_at=now() where game_id=p_game_id and region_code=p_region returning to_jsonb(game_fiscal_regions.*) into new_row;
 insert into fiscal_change_ledger(game_id,region_code,source_type,source_id,note,before_values,after_values,actor_id) values(p_game_id,p_region,'teacher',gen_random_uuid()::text,'Преподаватель изменил параметры учебного сценария',old_row,new_row,auth.uid());
end $$;
create or replace function public.propose_fiscal_rate(p_game_id uuid,p_region text,p_tax text,p_rate numeric) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$
declare t fiscal_tax_catalog%rowtype;d uuid;pid uuid;v_stage integer;roles text;subject text;
begin
 if not private.is_game_member(p_game_id) then raise exception 'Нет доступа к игре.';end if;
 select string_agg(rt,' ') into roles from private.formal_user_roles(p_game_id,auth.uid()) rt;
 if not private.is_game_teacher(p_game_id) and coalesce(roles,'') !~ 'министр|правительств|губернатор|глава|администрац' then raise exception 'Предложение ставки подготавливает представитель исполнительной власти.';end if;
 select * into t from fiscal_tax_catalog where tax_key=p_tax;
 if not found or t.default_rate is null then raise exception 'Для этого платежа используется специальная формула, а не единая ставка.';end if;
 if p_rate is null or p_rate<t.min_rate or p_rate>t.max_rate then raise exception 'Ставка вне диапазона выбранной налоговой базы.';end if;
 if t.level='federal' then p_region:='00';elsif not exists(select 1 from fiscal_region_reference where code=p_region) then raise exception 'Выберите регион.';end if;
 select coalesce(max(stage_no),1) into v_stage from game_stages where game_id=p_game_id and status='open';
 if t.level='federal' and private.can_create_formal_subject(p_game_id,auth.uid(),'government') then
  d:=public.create_formal_document(p_game_id,v_stage,'Об изменении ставки: '||t.label,'fz_bill','government','Правительство Российской Федерации','Проект федерального закона.\nСтатья 1. Изменить ставку налога «'||t.label||'» для выбранной учебной налоговой базы на '||p_rate||' '||t.unit||'.\nСтатья 2. Определить дату вступления в силу с учётом статьи 5 НК РФ.\nПояснительная записка: оценить выпадающие доходы, компенсацию и полномочия.\nТекст требуется доработать перед внесением.',null,null,null,'bill',jsonb_build_object('fiscal_rate_change',jsonb_build_object('region_code',p_region,'tax_key',p_tax,'rate',p_rate),'educational_draft',true));
 end if;
 insert into fiscal_rate_proposals(game_id,region_code,tax_key,new_rate,author_id,document_id) values(p_game_id,p_region,p_tax,p_rate,auth.uid(),d) returning id into pid;
 return pid;
end $$;
create or replace function public.apply_fiscal_rate_proposal(p_proposal uuid,p_document uuid default null) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$
declare p fiscal_rate_proposals%rowtype;d formal_documents%rowtype;old_rate numeric;begin
 select * into p from fiscal_rate_proposals where id=p_proposal for update;
 if p.id is null or not private.is_game_teacher(p.game_id) then raise exception 'Подтверждение налоговой меры доступно преподавателю.';end if;
 select * into d from formal_documents where id=coalesce(p_document,p.document_id) and game_id=p.game_id;
 if d.id is null or d.status_code<>'published' then raise exception 'Выберите опубликованный акт, которым введена ставка.';end if;
 if p.status<>'pending' then raise exception 'Мера уже рассмотрена.';end if;
 select rate into old_rate from game_fiscal_rates where game_id=p.game_id and region_code=p.region_code and tax_key=p.tax_key;
 insert into game_fiscal_rates(game_id,region_code,tax_key,rate) values(p.game_id,p.region_code,p.tax_key,p.new_rate) on conflict(game_id,region_code,tax_key) do update set rate=excluded.rate,updated_at=now();
 update fiscal_rate_proposals set status='applied',document_id=d.id where id=p.id;
 insert into fiscal_change_ledger(game_id,region_code,source_type,source_id,note,before_values,after_values,actor_id) values(p.game_id,p.region_code,'act',d.id::text||':'||p.tax_key,'Вступила в силу налоговая мера по '||d.registry_no,jsonb_build_object('rate',old_rate),jsonb_build_object('rate',p.new_rate),auth.uid());
end $$;
create or replace function private.fiscal_event_outcome() returns trigger language plpgsql security definer set search_path=public,private,pg_temp as $$
declare c event_cases%rowtype;fx jsonb;rc text;before_row jsonb;after_row jsonb;opt integer;
begin
 select * into c from event_cases where id=new.case_id;
 if coalesce(new.winner,'') !~ '^option_[0-9]+$' then return new;end if;
 opt:=substring(new.winner from 8)::integer-1;fx:=c.effect_plan->'options'->opt->'fiscal_effect';rc:=c.comic_scene->>'region_code';
 if fx is null or rc is null then return new;end if;
 if exists(select 1 from fiscal_change_ledger where game_id=c.game_id and source_type='event' and source_id=c.id::text and region_code=rc) then return new;end if;
 perform private.ensure_fiscal_game(c.game_id);
 select to_jsonb(r) into before_row from game_fiscal_regions r where game_id=c.game_id and region_code=rc for update;
 update game_fiscal_regions set enterprises=greatest(0,enterprises+coalesce((fx->>'enterprises')::int,0)),expenditure=greatest(0,expenditure+coalesce((fx->>'expenditure')::numeric,0)),transfer_in=greatest(0,transfer_in+coalesce((fx->>'transfer_in')::numeric,0)),activity_multiplier=greatest(.05,least(5,activity_multiplier+coalesce((fx->>'activity')::numeric,0))),cost_multiplier=greatest(.05,least(5,cost_multiplier+coalesce((fx->>'cost')::numeric,0))),updated_at=now() where game_id=c.game_id and region_code=rc returning to_jsonb(game_fiscal_regions.*) into after_row;
 insert into fiscal_change_ledger(game_id,region_code,source_type,source_id,note,before_values,after_values) values(c.game_id,rc,'event',c.id::text,'Исход кейса «'||c.title||'»',before_row,after_row);
 return new;
end $$;
create trigger fiscal_event_resolved after insert on event_case_outcomes for each row execute function private.fiscal_event_outcome();
revoke all on function public.get_fiscal_budget(uuid),public.set_fiscal_parameters(uuid,text,jsonb),public.propose_fiscal_rate(uuid,text,text,numeric),public.apply_fiscal_rate_proposal(uuid,uuid) from public,anon;
grant execute on function public.get_fiscal_budget(uuid),public.set_fiscal_parameters(uuid,text,jsonb),public.propose_fiscal_rate(uuid,text,text,numeric),public.apply_fiscal_rate_proposal(uuid,uuid) to authenticated;
revoke all on function private.ensure_fiscal_game(uuid),private.fiscal_event_outcome() from public,anon,authenticated;
